import{c as a,Q as t,j as r,m as n}from"./chunks/framework.BXc4yaFE.js";const u=JSON.parse('{"title":"Retrieval-Augmented Generation for Knowledge-Intensive NLP Tasks","description":"","frontmatter":{"url":"https://arxiv.org/abs/2005.11401","title":"Retrieval-Augmented Generation for Knowledge-Intensive NLP Tasks","archived_date":"2026-06-09T00:00:00.000Z","arxiv_id":2005.11401,"authors":["Patrick Lewis","Ethan Perez","Aleksandra Piktus","Fabio Petroni","Vladimir Karpukhin","Naman Goyal","Heinrich Küttler","Mike Lewis","Wen-tau Yih","Tim Rocktäschel","Sebastian Riedel","Douwe Kiela"],"pdf_path":"pdfs/2005.11401.pdf","published_date":"2020-05-22T00:00:00.000Z"},"headers":[],"relativePath":"research/papers/2020-05-22-rag-retrieval-augmented-generation-2005-11401.md","filePath":"research/papers/2020-05-22-rag-retrieval-augmented-generation-2005-11401.md","lastUpdated":1785909234000}'),i={name:"research/papers/2020-05-22-rag-retrieval-augmented-generation-2005-11401.md"};function o(s,e,d,l,c,h){return t(),r("div",null,[...e[0]||(e[0]=[n('<h2 id="abstract" tabindex="-1">Abstract <a class="header-anchor" href="#abstract" aria-label="Permalink to &quot;Abstract&quot;">​</a></h2><p>Large pre-trained language models have been shown to store factual knowledge in their parameters, and achieve state-of-the-art results when fine-tuned on downstream NLP tasks. However, their ability to access and precisely manipulate knowledge is still limited, and hence on knowledge-intensive tasks, their performance lags behind task-specific architectures. Additionally, providing provenance for their decisions and updating their world knowledge remain open research problems. Pre-trained models with a differentiable access mechanism to explicit non-parametric memory can overcome this issue, but have so far been only investigated for extractive downstream tasks. We explore a general-purpose fine-tuning recipe for retrieval-augmented generation (RAG) -- models which combine pre-trained parametric and non-parametric memory for language generation. We introduce RAG models where the parametric memory is a pre-trained seq2seq model and the non-parametric memory is a dense vector index of Wikipedia, accessed with a pre-trained neural retriever. We compare two RAG formulations, one which conditions on the same retrieved passages across the whole generated sequence, the other can use different passages per token. We fine-tune and evaluate our models on a wide range of knowledge-intensive NLP tasks and set the state-of-the-art on three open domain QA tasks, outperforming parametric seq2seq models and task-specific retrieve-and-extract architectures. For language generation tasks, we find that RAG models generate more specific, diverse and factual language than a state-of-the-art parametric-only seq2seq baseline.</p><h2 id="主要貢獻" tabindex="-1">主要貢獻 <a class="header-anchor" href="#主要貢獻" aria-label="Permalink to &quot;主要貢獻&quot;">​</a></h2><ul><li><strong>RAG 框架（Retrieval-Augmented Generation）</strong>：結合預訓練參數記憶（seq2seq 模型）與非參數記憶（Wikipedia 密集向量索引），為語言生成任務提供通用 fine-tuning 方案。</li><li><strong>兩種 RAG 變體</strong>： <ul><li><strong>RAG-Sequence</strong>：整個生成序列使用同一份檢索文件；對每份文件獨立執行 beam search 後合併。</li><li><strong>RAG-Token</strong>：每個 token 可使用不同的檢索文件，允許生成時從多份文件中取用不同知識。</li></ul></li><li><strong>端到端訓練</strong>：Retriever（DPR，基於 BERT 的雙編碼器）與 Generator（BART-large）聯合訓練，無需對檢索文件的直接監督信號。</li><li><strong>Open-domain QA SOTA</strong>：在 Natural Questions、WebQuestions、CuratedTrec 三個開放域 QA 任務上達到當時最優，優於參數式 seq2seq 模型和特定任務的 retrieve-and-extract 架構。</li><li><strong>更好的語言生成品質</strong>：相較於純參數 seq2seq baseline，RAG 生成的文本更具體、多元且真實。</li><li><strong>可更新知識</strong>：非參數記憶（向量索引）可直接替換以更新模型的世界知識，無需重新訓練。</li><li><strong>歷史意義</strong>：RAG 是現代 LLM 應用中最廣泛採用的知識增強範式，直接影響了後續所有 RAG 系統的設計。</li></ul><h2 id="論文全文" tabindex="-1">論文全文 <a class="header-anchor" href="#論文全文" aria-label="Permalink to &quot;論文全文&quot;">​</a></h2><p><strong>Title</strong>: Retrieval-Augmented Generation for Knowledge-Intensive NLP Tasks <strong>Authors</strong>: Patrick Lewis, Ethan Perez, Aleksandra Piktus, Fabio Petroni, Vladimir Karpukhin, Naman Goyal, Heinrich Küttler, Mike Lewis, Wen-tau Yih, Tim Rocktäschel, Sebastian Riedel, Douwe Kiela <strong>Affiliations</strong>: Facebook AI Research; University College London; New York University <strong>arXiv ID</strong>: 2005.11401 (v4, revised 2021-04-12) <strong>Published</strong>: 2020-05-22 <strong>Venue</strong>: NeurIPS 2020 <strong>URL</strong>: <a href="https://arxiv.org/abs/2005.11401" target="_blank" rel="noreferrer">https://arxiv.org/abs/2005.11401</a><strong>Code</strong>: <a href="https://github.com/huggingface/transformers" target="_blank" rel="noreferrer">https://github.com/huggingface/transformers</a> (RAG implementation)</p><h3 id="full-abstract" tabindex="-1">Full Abstract <a class="header-anchor" href="#full-abstract" aria-label="Permalink to &quot;Full Abstract&quot;">​</a></h3><p>Large pre-trained language models have been shown to store factual knowledge in their parameters, and achieve state-of-the-art results when fine-tuned on downstream NLP tasks. However, their ability to access and precisely manipulate knowledge is still limited, and hence on knowledge-intensive tasks, their performance lags behind task-specific architectures. Additionally, providing provenance for their decisions and updating their world knowledge remain open research problems. Pre-trained models with a differentiable access mechanism to explicit non-parametric memory have so far been only investigated for extractive downstream tasks. We explore a general-purpose fine-tuning recipe for retrieval-augmented generation (RAG) — models which combine pre-trained parametric and non-parametric memory for language generation. We introduce RAG models where the parametric memory is a pre-trained seq2seq model and the non-parametric memory is a dense vector index of Wikipedia, accessed with a pre-trained neural retriever. We compare two RAG formulations, one which conditions on the same retrieved passages across the whole generated sequence, and another which can use different passages per token. We fine-tune and evaluate our models on a wide range of knowledge-intensive NLP tasks and set the state of the art on three open domain QA tasks, outperforming parametric seq2seq models and task-specific retrieve-and-extract architectures. For language generation tasks, we find that RAG models generate more specific, diverse and factual language than a state-of-the-art parametric-only seq2seq baseline.</p><h3 id="_1-introduction" tabindex="-1">1 Introduction <a class="header-anchor" href="#_1-introduction" aria-label="Permalink to &quot;1 Introduction&quot;">​</a></h3><p>Pre-trained neural language models have been shown to learn a substantial amount of in-depth knowledge from data. They can do so without any access to an external memory, as a parameterized implicit knowledge base. While this development is exciting, such models do have downsides: They cannot easily expand or revise their memory, can&#39;t straightforwardly provide insight into their predictions, and may produce &quot;hallucinations.&quot;</p><p>Hybrid models that combine parametric memory with non-parametric (i.e., retrieval-based) memories can address some of these issues because knowledge can be directly revised and expanded, and accessed knowledge can be inspected and interpreted. REALM and ORQA, two recently introduced models that combine masked language models with a differentiable retriever, have shown promising results, but have only explored open-domain extractive question answering.</p><p>Here, we bring hybrid parametric and non-parametric memory to the &quot;workhorse of NLP,&quot; i.e. sequence-to-sequence (seq2seq) models. We build RAG models where the parametric memory is a pre-trained seq2seq transformer, and the non-parametric memory is a dense vector index of Wikipedia, accessed with a pre-trained neural retriever. We combine these components in a probabilistic model trained end-to-end.</p><h3 id="_2-methods" tabindex="-1">2 Methods <a class="header-anchor" href="#_2-methods" aria-label="Permalink to &quot;2 Methods&quot;">​</a></h3><p>RAG models use the input sequence x to retrieve text documents z and use them as additional context when generating the target sequence y. Our models leverage two components:</p><ol><li><strong>Retriever</strong> p_η(z|x): Parameters η that return (top-K truncated) distributions over text passages given a query x</li><li><strong>Generator</strong> p_θ(y_i|x,z,y_<code>{1:i-1}</code>): Generates current token based on context of previous tokens, original input x, and retrieved passage z</li></ol><h4 id="_2-1-rag-sequence-model" tabindex="-1">2.1 RAG-Sequence Model <a class="header-anchor" href="#_2-1-rag-sequence-model" aria-label="Permalink to &quot;2.1 RAG-Sequence Model&quot;">​</a></h4><p>Uses the same retrieved document to generate the complete sequence. Retrieves top K documents, generator produces output sequence probability for each document, then marginalizes:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>p_RAG-Sequence(y|x) ≈ Σ_{z ∈ top-k} p_η(z|x) · p_θ(y|x,z)</span></span></code></pre></div><h4 id="_2-2-rag-token-model" tabindex="-1">2.2 RAG-Token Model <a class="header-anchor" href="#_2-2-rag-token-model" aria-label="Permalink to &quot;2.2 RAG-Token Model&quot;">​</a></h4><p>Can draw a different latent document for each target token and marginalize accordingly. This allows the generator to choose content from several documents when producing an answer:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>p_RAG-Token(y|x) ≈ Π_i Σ_{z ∈ top-k} p_η(z|x) · p_θ(y_i|x,z,y_{1:i-1})</span></span></code></pre></div><h4 id="_2-3-retriever-dpr" tabindex="-1">2.3 Retriever: DPR <a class="header-anchor" href="#_2-3-retriever-dpr" aria-label="Permalink to &quot;2.3 Retriever: DPR&quot;">​</a></h4><p>The retrieval component is based on DPR (Dense Passage Retriever). DPR follows a bi-encoder architecture using BERT-based encoders for both documents and queries. Top-k retrieval is a Maximum Inner Product Search (MIPS) problem, approximately solved in sub-linear time using FAISS.</p><p>We use a pre-trained bi-encoder from DPR to initialize our retriever and build the document index (referred to as non-parametric memory).</p><h4 id="_2-4-generator-bart" tabindex="-1">2.4 Generator: BART <a class="header-anchor" href="#_2-4-generator-bart" aria-label="Permalink to &quot;2.4 Generator: BART&quot;">​</a></h4><p>The generator component is BART-large, a pre-trained seq2seq transformer with 400M parameters. To combine the input x with the retrieved content z, we simply concatenate them. BART was pre-trained using a denoising objective and achieves state-of-the-art results on a diverse set of generation tasks.</p><h4 id="_2-5-training" tabindex="-1">2.5 Training <a class="header-anchor" href="#_2-5-training" aria-label="Permalink to &quot;2.5 Training&quot;">​</a></h4><p>We jointly train the retriever and generator components without any direct supervision on what document should be retrieved. We minimize the negative marginal log-likelihood of each target using Adam. We keep the document encoder fixed and only fine-tune the query encoder and the BART generator.</p><h4 id="_2-6-decoding" tabindex="-1">2.6 Decoding <a class="header-anchor" href="#_2-6-decoding" aria-label="Permalink to &quot;2.6 Decoding&quot;">​</a></h4><ul><li><strong>RAG-Token</strong>: Standard autoregressive seq2seq decoding via beam search.</li><li><strong>RAG-Sequence</strong>: Run beam search for each retrieved document z separately, yielding hypothesis set Y. Use &quot;Thorough Decoding&quot; (additional forward passes) or &quot;Fast Decoding&quot; (approximation) to estimate marginal probabilities.</li></ul><h3 id="_3-experiments" tabindex="-1">3 Experiments <a class="header-anchor" href="#_3-experiments" aria-label="Permalink to &quot;3 Experiments&quot;">​</a></h3><p><strong>Document index</strong>: December 2018 Wikipedia dump split into 21M disjoint 100-word chunks. Document embeddings computed with DPR encoder, indexed with FAISS HNSW.</p><h4 id="_3-1-open-domain-question-answering" tabindex="-1">3.1 Open-domain Question Answering <a class="header-anchor" href="#_3-1-open-domain-question-answering" aria-label="Permalink to &quot;3.1 Open-domain Question Answering&quot;">​</a></h4><p>Evaluated on Natural Questions (NQ), TriviaQA (TQA), WebQuestions (WQ), and CuratedTrec (CT). RAG sets the state of the art on NQ, WQ, and CT, outperforming both:</p><ul><li>Extractive QA approaches (retrieve then extract spans)</li><li>&quot;Closed-Book QA&quot; (pure parametric, no retrieval)</li></ul><p>On TriviaQA, RAG strongly outperforms T5 and approaches pipeline systems that use gold passages.</p><h4 id="_3-2-abstractive-question-answering" tabindex="-1">3.2 Abstractive Question Answering <a class="header-anchor" href="#_3-2-abstractive-question-answering" aria-label="Permalink to &quot;3.2 Abstractive Question Answering&quot;">​</a></h4><p>Evaluated on MS-MARCO NLG task without using supplied gold passages. RAG generates more fluent, factual answers compared to pure parametric baselines. Some questions require real-time information (weather, prices) that cannot be answered from Wikipedia alone—RAG falls back on parametric knowledge.</p><h4 id="_3-3-jeopardy-question-generation" tabindex="-1">3.3 Jeopardy Question Generation <a class="header-anchor" href="#_3-3-jeopardy-question-generation" aria-label="Permalink to &quot;3.3 Jeopardy Question Generation&quot;">​</a></h4><p>Novel task: given an answer entity (e.g., &quot;The World Cup&quot;), generate the corresponding Jeopardy question. RAG generates more specific, factual, and diverse questions than BART baseline. Human evaluation confirms RAG outputs are more factual.</p><h4 id="_3-4-fact-verification-fever" tabindex="-1">3.4 Fact Verification (FEVER) <a class="header-anchor" href="#_3-4-fact-verification-fever" aria-label="Permalink to &quot;3.4 Fact Verification (FEVER)&quot;">​</a></h4><p>RAG achieves results within 4.3% of state-of-the-art pipeline models that use strong retrieval supervision, despite being trained end-to-end without retrieval supervision.</p><h4 id="_3-5-knowledge-updatability" tabindex="-1">3.5 Knowledge Updatability <a class="header-anchor" href="#_3-5-knowledge-updatability" aria-label="Permalink to &quot;3.5 Knowledge Updatability&quot;">​</a></h4><p>Demonstrates that replacing the non-parametric memory (document index) updates the model&#39;s knowledge without retraining. This is a key advantage over purely parametric models.</p><h3 id="_4-related-work" tabindex="-1">4 Related Work <a class="header-anchor" href="#_4-related-work" aria-label="Permalink to &quot;4 Related Work&quot;">​</a></h3><ul><li><strong>Extractive QA with retrieval</strong>: DPR, ORQA, REALM—focused on extractive span selection</li><li><strong>Parametric knowledge</strong>: T5, GPT-2/3—store knowledge in weights, cannot easily update</li><li><strong>Memory-augmented networks</strong>: Memory networks, stack-augmented networks—train from scratch</li><li><strong>RAG novelty</strong>: First to combine pre-trained parametric (BART) and non-parametric (DPR index) memory for generative NLP with end-to-end training</li></ul><h3 id="_5-conclusion" tabindex="-1">5 Conclusion <a class="header-anchor" href="#_5-conclusion" aria-label="Permalink to &quot;5 Conclusion&quot;">​</a></h3><p>RAG models combine the best of parametric and non-parametric memory for NLP. They set state-of-the-art on open-domain QA tasks, generate more specific and factual language than pure parametric models, and allow knowledge updates by replacing the document index. RAG is a general-purpose framework applicable to any seq2seq task.</p><p>The framework has become the foundational blueprint for modern LLM knowledge augmentation systems, with adaptations in virtually every production RAG pipeline (LangChain, LlamaIndex, etc.).</p><p><strong>Key results summary</strong>:</p><ul><li>NQ Exact Match: RAG-Token 44.5% vs. DPR 41.5% vs. T5-11B 34.5%</li><li>TQA EM (wiki): RAG-Sequence 56.8% vs. T5-11B 37.4%</li><li>MS-MARCO BLEU-1: RAG 45.1% vs. BART 43.1%</li><li>FEVER label accuracy: RAG 74.3% vs. pipeline SOTA 78.3%</li></ul>',51)])])}const m=a(i,[["render",o]]);export{u as __pageData,m as default};
